const raw  = $input.first().json;
const body = raw.body || raw;

const message = (body.message || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];

if (!message) throw new Error('Empty message — skip');

// Build the full conversation for the LLM
const systemPrompt = `You are HotBot, the AI assistant for HotBot Studios — a US-based AI automation and digital marketing agency.

Your role:
- Help website visitors understand HotBot Studios services
- Answer questions about AI automation, digital marketing, content, PR, UI/UX, software development
- Collect lead information when users show buying intent (name, email, service interest)
- Be concise, professional, and friendly
- Always encourage next steps: book a call, fill out the form, or contact the team

HotBot Studios services:
- AI Automation (n8n, chatbots, voice AI, workflow automation)
- Digital Marketing (SEO, PPC, social media, email marketing)
- Content Studio (blog, video, copywriting)
- Software Development (web apps, SaaS, API integrations)
- Public Relations (media coverage, brand authority)
- UI/UX Design (product design, prototyping)
- Marketing Consulting

Contact: hello@hotbotstudios.com | hotbotstudios.com

If a user wants to book a call, schedule, or speak with a human: tell them to click the Call tab in this chat or fill out the contact form.
If a user asks for a quote or pricing: collect their name, email, service interest, and budget range.
Keep all responses under 120 words unless the user asks for detail.`;

const messages = [
  { role: 'system', content: systemPrompt },
  ...history.map((h) => ({ role: h.role, content: h.content })),
  { role: 'user', content: message }
];

return [{ json: { message, history, messages, receivedAt: new Date().toISOString() } }];

const aiReply   = $input.first().json?.message?.content || $input.first().json?.choices?.[0]?.message?.content || '';
const userMsg   = $('Extract Chat Payload').first().json.message.toLowerCase();

// Simple rule-based intent detection
const bookingWords  = ['book', 'call', 'schedule', 'talk', 'speak', 'meet', 'appointment', 'demo', 'zoom', 'consult'];
const humanWords    = ['human', 'person', 'agent', 'team', 'real person', 'talk to someone', 'representative'];
const quoteWords    = ['price', 'cost', 'quote', 'pricing', 'how much', 'budget', 'rate', 'package'];

const wantsBooking  = bookingWords.some((w) => userMsg.includes(w));
const wantsHuman    = humanWords.some((w)   => userMsg.includes(w));
const wantsQuote    = quoteWords.some((w)   => userMsg.includes(w));

const intent = wantsHuman ? 'human_handoff' : wantsBooking ? 'booking' : wantsQuote ? 'quote' : 'general';

const suggestForm  = wantsBooking || wantsQuote;
const suggestCall  = wantsHuman   || wantsBooking;

return [{ json: {
  reply:       aiReply,
  intent,
  suggestForm,
  suggestCall,
  userMessage: $('Extract Chat Payload').first().json.message,
  receivedAt:  $('Extract Chat Payload').first().json.receivedAt
}}];
